  async function ensureLibrarySeedV2(){
    try{
      if(localStorage.getItem('seeded_library_v2')) return;
      const list = await getLibrary();
      const existingTitles = new Set(list.map(x=> (x.title||'').trim().toLowerCase()));
      let added = 0;
      for(const item of DEFAULT_LIBRARY_SEED){
        if(!existingTitles.has(item.title.trim().toLowerCase())){
          list.push(item);
          added++;
        }
      }
      if(added>0) await setLibrary(list);
      localStorage.setItem('seeded_library_v2','1');
    }catch(e){}
  }

