  // Подставляем вторую ссылку (video2) в TERMINOLOGY_DATA.techniques по romaji.
  // Выполняется сразу после объявления TERMINOLOGY_DATA ниже (см. вызов attachDriveVideos()).
  function attachDriveVideos(){
    try{
      Object.keys(DRIVE_TECHNIQUE_VIDEOS).forEach(function(romaji){
        const t = TERMINOLOGY_DATA.techniques.find(function(x){ return x.romaji === romaji; });
        if(t) t.video2 = 'https://drive.google.com/file/d/' + DRIVE_TECHNIQUE_VIDEOS[romaji] + '/view';
      });
    }catch(e){}
  }
