  const REFEREE_RULES_DATA = [
    { num:'Жесты', title:'Жесты арбитра (Статья 4)', text:'ХАДЖИМЭ / СОРЭ-МАДЭ — команды начала/конца. ИППОН — рука высоко над головой ладонью вперёд. ВАЗА-АРИ — рука в сторону на уровне плеча ладонью вниз. ВАЗА-АРИ-АВАСЕТЕ-ИППОН — сначала жест Ваза-ари, затем Иппон. ЮКО — рука в сторону под 45° ладонью вниз. ОСАЕКОМИ — рука вперёд ладонью вниз в сторону участников. ТОКЕТА — рука вперёд, пальцы прямые, помахать 2-3 раза. МАТЭ — рука вперёд параллельно татами на уровне плеча, ладонью вперёд. СОНО-МАМА/ЁШИ — коснуться ладонями обоих участников. ВСТАТЬ — обе руки к дзюдоисту ладонями вверх, движение снизу вверх. ШИДО/ХАНСОКУ-МАКЭ — указательный палец в сторону наказываемого из сжатого кулака. НЕ ЗАСЧИТЫВАЕТСЯ — рука над головой, взмах справа налево. КАЧИ (победитель) — шаг вперёд, указать рукой ладонью внутрь выше плеча.' },
    { num:'Ст.1-4', title:'Судьи и функции арбитра', text:'Возраст континентальных судей — 25–45 лет, международных — 30–50 лет на год экзамена. Судьи Мирового тура — не старше 55 лет в течение олимпийского цикла. С 1 января 2026 — обязателен сертификат Академии МФД (Уровень 1/UCJI). Поединок судит арбитр национальности, отличной от обеих сторон. Белый дзюдоист — справа от арбитра, синий — слева.' },
    { num:'Ст.5', title:'Место (зона действия)', text:'Поединок проводится в рабочей зоне. Действие продолжается без Матэ, если хотя бы часть тела касается рабочей зоны и действие начато внутри. Бросок, начатый внутри зоны и завершённый в пределах 2м зоны безопасности — засчитывается. Удержание/болевой/удушение, начатые внутри зоны, могут продолжаться за её пределами.' },
    { num:'Ст.6-9', title:'Время поединка и начало встречи', text:'Взрослые, юниоры, кадеты — 4 минуты чистого времени. Между поединками — 10 минут отдыха. Время удержания: Иппон — 20 сек, Ваза-ари — 10-19 сек, Юко — 5-9 сек. Участники не пожимают руки перед поединком. Встреча начинается по команде Хаджимэ, когда оба стоят с надлежаще заправленными дзюдоги.' },
    { num:'Ст.10', title:'Переход стойка ↔ партер', text:'Переход в партер действителен при реальной атаке/контратаке с попыткой удержания, болевого или удушения. Стойка — когда оба спортсмена стоят и не в позициях партера. Захват ниже пояса в завершающей фазе броска разрешён. Участник на коленях не может захватывать ноги соперника руками для защиты от броска — иначе Шидо.' },
    { num:'Ст.11', title:'Команда «Матэ»', text:'Матэ даётся: при полном выходе за зону без непрерывного действия; при запрещённых действиях; при травме; для приведения дзюдоги/причёски в порядок; при отсутствии развития в партере; при подготовительных ударных/борцовских действиях (не дзюдо); при достижении отметки 2м в зоне безопасности. Матэ НЕ даётся при продолжающемся у границы зоны действии или отдыхе после освобождения от удержания.' },
    { num:'Ст.12-13', title:'Соно-мама и окончание поединка', text:'Соно-мама — «не двигаться», только в партере. Победа в основное время: по оценке (Юко/Ваза-ари/Иппон), прямому/непрямому Хансоку-макэ, Фусен-гачи или Кикен-гачи. Наказание никогда не приравнивается к оценке.' },
    { num:'Ст.13.4', title:'Голден скор', text:'Если оценки равны или их нет — Голден скор без ограничения по времени, без перерыва. Все оценки/наказания переносятся. Победа — по любой технической оценке, Хансоку-макэ или Кикен-гачи. Удержание, начатое в Голден скор: через 5 сек удержания — Юко и конец поединка.' },
    { num:'Ст.14', title:'Иппон', text:'4 критерия: скорость, сила, падение на спину, контроль до конца приземления. Присуждается за бросок на спину классифицированной техникой Кодокан. Сознательный «мост» (голова и стопа/стопы касаются татами после броска) = Иппон, из соображений безопасности. В партере: удержание 20 сек, двукратный хлопок/сдача «Маита», потеря сознания от удушения/болевого.' },
    { num:'Ст.15-16', title:'Ваза-ари, Юко, Ваза-ари-авасете-иппон', text:'Ваза-ари: приземление на бок по линии плеч под углом >90°, но не на спину, без всех 4 критериев Иппона. Юко: приземление на бок к животу, верх спины, шею, ягодицу с опорой на локоть/руку. Юко НЕ засчитывается, если живот/бёдра/колени коснулись татами раньше или одновременно. В партере: Ваза-ари — удержание 10-19 сек, Юко — 5-9 сек. Второе Ваза-ари = Иппон.' },
    { num:'Ст.17', title:'Удержание (Осаекоми)', text:'Объявляется, когда удерживаемый контролируется сбоку/сзади/сверху и касается татами спиной или верхней частью спины полностью. Удерживающий не должен быть под контролем ног противника. Запрещено удержание только за голову/шею без контроля хотя бы одной руки — это Матэ (в партере) или Матэ+Шидо (в не-ваза с ногами).' },
    { num:'Ст.18.1', title:'Шидо — незначительные нарушения', text:'2 Шидо — предупреждения, 3-е — Хансоку-макэ. Наказываются: пассивность/оборонительная стойка; ложная атака; уход от захвата более 45 сек; выход за зону без атаки; упор в лицо; умышленный уход от захвата; захват ниже пояса/ног/брюк; нырок под руку без атаки; нога между ног соперника без атаки; удержание края рукавов; блокировка пальцев/кистей; заламывание пальцев; срыв захвата двумя руками без сохранения; неопрятная дзюдоги/причёска; затягивание времени.' },
    { num:'Ст.18.2', title:'Хансоку-макэ — грубые нарушения', text:'За опасную технику (участник МОЖЕТ продолжать): ныряние головой в Учи-мата, Хараи-госи, Сеой-нагэ и т.п. За действия против духа дзюдо (участник НЕ МОЖЕТ продолжать): Кавадзу-гакэ, Кани-басами, дожимэ; болевые не на локоть; болевые/удушения в стойке без броска с высоким риском травмы; захваты санкаку с высоким риском травмы шеи/позвоночника; неподчинение арбитру; оскорбления; металлические предметы; любое анти-дзюдо поведение.' },
    { num:'Ст.19', title:'Неявка и отказ', text:'Фусен-гачи — победа при неявке соперника (правило 30 секунд после последнего предупреждения). Кикен-гачи — победа при отказе соперника от продолжения (травма, болезнь, добровольный отказ).' },
    { num:'Ст.20', title:'Травма, болезнь, несчастный случай', text:'Если травма — по вине травмированного, он проигрывает. Кровотечение — не более 2 раз медпомощи, на 3-й — поражение по Кикен-гачи. Вывихнутый палец — вправление разрешено дважды, на 3-й раз — поражение. Просьба спортсмена или врача вызвать врача во время схватки = поражение по Кикен-гачи (кроме экстренных случаев угрозы здоровью).' },
    { num:'D1.1', title:'Философия и культура судейства', text:'Дзюдо — метод физического, интеллектуального и нравственного воспитания. Единственная цель — Иппон; все прочие оценки — способ его достичь. Судьи — защитники физического, культурного и философского выражения дзюдо. «Дзюдо необходимо понимать, чтобы его ценить!»' }
  ];

